SET code      = #{code},
    `date`    = #{date},
    reason    = #{reason},
    `action`  = #{action},
    frequency = #{frequency},
    amount    = #{amount},
    note      = #{note}
WHERE adjustment_id = #{adjustmentId}
  AND user_id = #{userId}

